// Обробник помилок логбука.
// Свідомо НЕ звертається до Postgres: якщо впала саме база, обробник
// мусить лишитися здатним повідомити. Тому chat_id зашитий константою.

const CHAT_ID = '-1004302974909';   // група ROTES Logbook

const j = $input.first().json || {};
const wf = j.workflow || {};
const ex = j.execution || {};
const err = ex.error || {};

const esc = s => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const when = new Date().toLocaleString('uk-UA', { timeZone: 'America/Moncton' });

const lines = [
  '🛑 <b>Помилка у логбуці</b>',
  '',
  `<b>Воркфлоу:</b> ${esc(wf.name || 'невідомо')}`,
  `<b>Вузол:</b> ${esc(ex.lastNodeExecuted || 'невідомо')}`,
  `<b>Час:</b> ${esc(when)}`,
  '',
  `<b>Причина:</b>\n<code>${esc(String(err.message || 'без повідомлення').slice(0, 500))}</code>`
];

if (ex.url) lines.push('', `<a href="${esc(ex.url)}">відкрити виконання</a>`);

lines.push('', '<i>Поїздки за цей період могли не записатися. Перевір після виправлення.</i>');

return [{ json: { chat_id: CHAT_ID, text: lines.join('\n') } }];
